// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for the attended flow: ru-flow-queu and ru-wait-hand on the sim
// Flo: plan a flow > run live on the sim > inject captcha, lock, failures > assert states, notifications, cool pace
// I/O: sim page + memory store > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const fq = @import("ru-flow-queu.zig"); const appr = @import("ru-appr-list.zig"); const flo = @import("st-flow-data.zig"); const halt = @import("ru-safe-halt.zig"); const file = @import("st-stor-file.zig"); const rig = @import("te-rigz-main.zig"); const sess = @import("ru-sess-ctxz.zig"); const T = std.testing;
fn cfgFlow() @import("cf-conf-load.zig").Conf { var cfg = rig.cfgOf(); cfg.noti_chai_orde = &.{"file"}; cfg.wait_dead_mins = 1; cfg.wait_sett_mins = 1; return cfg; }
fn statDir(tmpz: *std.testing.TmpDir, buff: []u8) ![]const u8 { return std.fmt.bufPrint(buff, ".zig-cache/tmp/{s}/stat", .{tmpz.sub_path}); }
test "happy flow: three items run by themselves, flow done, page changed" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgFlow(), .live); const fl = try appr.planFlow(&rg.sto, rg.aren.allocator(), "u", "t", &.{ "send Mom hello", "pin Boss", "remind Mom at 8 to buy milk" }, 1); const res = try fq.run(&ses, fl, .{}); try T.expect(res.kind == .done); try T.expectEqual(@as(u32, 3), res.done); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.sent.length")); try T.expectEqualStrings("Boss", try rg.js("Z.st.pin[0]")); try T.expectEqualStrings("buy milk|8", try rg.js("Z.st.rems[0]")); try T.expectEqualStrings("done", (try flo.flowLatest(&rg.sto, rg.aren.allocator())).?.state); const its = try flo.itemsOf(&rg.sto, rg.aren.allocator(), fl); for (its) |itm| try T.expectEqualStrings("done", itm.state); }
test "unapproved ask item is skipped without blocking; approving later runs it" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgFlow(), .live); const alo = rg.aren.allocator(); const fl = try appr.planFlow(&rg.sto, alo, "u", "t", &.{ "group Family", "send Mom hi" }, 1); const res = try fq.run(&ses, fl, .{}); try T.expectEqual(@as(u32, 1), res.done); try T.expectEqual(@as(u32, 1), res.skip); try T.expectEqualStrings("partial", (try flo.flowLatest(&rg.sto, alo)).?.state); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.grp.length")); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.sent.length")); try T.expectEqual(@as(u32, 1), try appr.approve(&rg.sto, alo, fl, "all")); ses.fake_ms += 600000; const again = try fq.run(&ses, fl, .{}); try T.expectEqual(@as(u32, 1), again.done); try T.expectEqualStrings("Family", try rg.js("Z.st.grp[0]")); }
test "one failing item parks only that item, the rest run, end lines say what to fix" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgFlow(), .live); const alo = rg.aren.allocator(); const fl = try appr.planFlow(&rg.sto, alo, "u", "t", &.{ "send Nobody hi", "send Anna ambiguous", "send Mom ok" }, 1); const res = try fq.run(&ses, fl, .{}); try T.expectEqual(@as(u32, 1), res.done); try T.expectEqual(@as(u32, 2), res.unsure); try T.expect(res.kind == .done); var found: u32 = 0; for (res.lines) |ln| { if (std.mem.find(u8, ln, "needs you") != null) found += 1; } try T.expectEqual(@as(u32, 2), found); const its = try flo.itemsOf(&rg.sto, alo, fl); try T.expectEqualStrings("unsure", its[0].state); try T.expectEqualStrings("unsure", its[1].state); try T.expectEqualStrings("done", its[2].state); }
test "needs-you captcha: flow waits, owner clears it, it settles, resumes the same item at cool pace, one intervention" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var sb: [160]u8 = undefined; const stat = try statDir(&tmpz, &sb); var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgFlow(), .live); const alo = rg.aren.allocator(); const fl = try appr.planFlow(&rg.sto, alo, "u", "t", &.{ "send Mom after captcha", "pin Boss" }, 1); _ = try rg.js("Z.overlay('captcha');Z.later(200,function(){Z.clearOverlay()});'x'"); const res = try fq.run(&ses, fl, .{ .stat = stat }); try T.expect(res.kind == .done); try T.expectEqual(@as(u32, 2), res.done); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.sent.length")); try T.expectEqual(@as(i64, 1), try flo.metaInt(&rg.sto, alo, "interv_n", 0)); try T.expect(try flo.metaInt(&rg.sto, alo, "cool_until", 0) > ses.now()); try T.expect((try rg.sto.haltGet(alo)) == null); try T.expect(try ses.cooling()); const alerts = try file.fileRead(alo, T.io, try std.fs.path.join(alo, &.{ stat, "alerts.txt" }), 4096); try T.expect(std.mem.find(u8, alerts, "Solve it in the open Zalo window") != null); try T.expect(std.mem.find(u8, alerts, "after captcha") == null); try T.expect(try flo.metaInt(&rg.sto, alo, "wait_ms", 0) > 0); }
test "wait deadline parks the flow; restart after the owner cleared it resumes with no second challenge" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var sb: [160]u8 = undefined; const stat = try statDir(&tmpz, &sb); var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgFlow(), .live); const alo = rg.aren.allocator(); const fl = try appr.planFlow(&rg.sto, alo, "u", "t", &.{ "send Mom parked then done", "pin Boss" }, 1); _ = try rg.js("Z.overlay('captcha');'x'"); const res = try fq.run(&ses, fl, .{ .stat = stat }); try T.expect(res.kind == .parked); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.sent.length")); try T.expectEqualStrings("wait", (try flo.flowLatest(&rg.sto, alo)).?.state); const its = try flo.itemsOf(&rg.sto, alo, fl); try T.expectEqualStrings("wait", its[0].state); _ = try rg.js("Z.clearOverlay();'x'"); var again = rg.ses(cfgFlow(), .live); again.fake_ms = ses.fake_ms + 600000; const res2 = try fq.run(&again, fl, .{ .stat = stat }); try T.expect(res2.kind == .done); try T.expectEqual(@as(u32, 2), res2.done); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.sent.length")); try T.expectEqual(@as(i64, 1), try flo.metaInt(&rg.sto, alo, "interv_n", 0)); }
test "unsafe lock page stops the whole flow, no auto resume, cooldown set, owner notified" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var sb: [160]u8 = undefined; const stat = try statDir(&tmpz, &sb); var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgFlow(), .live); const alo = rg.aren.allocator(); const fl = try appr.planFlow(&rg.sto, alo, "u", "t", &.{ "send Mom locked out", "pin Boss" }, 1); _ = try rg.js("Z.overlay('lock');'x'"); const res = try fq.run(&ses, fl, .{ .stat = stat }); try T.expect(res.kind == .unsafe); try T.expectEqual(@as(u32, 0), res.done); try T.expectEqualStrings("stop", (try flo.flowLatest(&rg.sto, alo)).?.state); try T.expect(try flo.metaInt(&rg.sto, alo, "cool_until", 0) > ses.now()); const alerts = try file.fileRead(alo, T.io, try std.fs.path.join(alo, &.{ stat, "alerts.txt" }), 4096); try T.expect(std.mem.find(u8, alerts, "lock or warning") != null); _ = try rg.js("Z.clearOverlay();'x'"); var again = rg.ses(cfgFlow(), .live); again.fake_ms = ses.fake_ms + 600000; const res2 = try fq.run(&again, fl, .{ .stat = stat }); try T.expect(res2.kind == .unsafe); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.sent.length")); try T.expect(try halt.classOf(&rg.sto, alo) == .unsf); }
test "a second challenge inside 24 hours is unsafe, never a second wait" { var tmpz = std.testing.tmpDir(.{}); defer tmpz.cleanup(); var sb: [160]u8 = undefined; const stat = try statDir(&tmpz, &sb); var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgFlow(), .live); const alo = rg.aren.allocator(); try flo.metaPutInt(&rg.sto, "chal_ts", rig.NOON - 3600000); const fl = try appr.planFlow(&rg.sto, alo, "u", "t", &.{"send Mom x"}, 1); _ = try rg.js("Z.overlay('captcha');Z.later(100,function(){Z.clearOverlay()});'x'"); const res = try fq.run(&ses, fl, .{ .stat = stat }); try T.expect(res.kind == .unsafe); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.sent.length")); try T.expectEqual(@as(i64, 0), try flo.metaInt(&rg.sto, alo, "interv_n", 0)); }
test "quiet hours pause the flow and keep the item; later run finishes" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var cfg = cfgFlow(); cfg.loca_utcz_mins = 0; var ses = rg.ses(cfg, .live); ses.fake_ms = 100 * 86400000 + 2 * 3600000; const alo = rg.aren.allocator(); const fl = try appr.planFlow(&rg.sto, alo, "u", "t", &.{"send Mom night"}, 1); const res = try fq.run(&ses, fl, .{}); try T.expect(res.kind == .blocked); try T.expectEqualStrings("pause", (try flo.flowLatest(&rg.sto, alo)).?.state); try T.expectEqualStrings("todo", (try flo.itemsOf(&rg.sto, alo, fl))[0].state); ses.fake_ms = 100 * 86400000 + 12 * 3600000; const res2 = try fq.run(&ses, fl, .{}); try T.expect(res2.kind == .done); try T.expectEqual(@as(i64, 1), try rg.num("Z.st.sent.length")); }
test "dry run previews every item and changes no state" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(cfgFlow(), .dry); const alo = rg.aren.allocator(); const fl = try appr.planFlow(&rg.sto, alo, "u", "t", &.{ "send Mom a", "send Boss b", "group Fam" }, 1); const res = try fq.run(&ses, fl, .{}); try T.expect(res.kind == .preview); try T.expectEqual(@as(u32, 2), res.done); try T.expectEqual(@as(u32, 1), res.skip); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.sent.length")); const its = try flo.itemsOf(&rg.sto, alo, fl); for (its) |itm| try T.expectEqualStrings("todo", itm.state); try T.expectEqualStrings("plan", (try flo.flowLatest(&rg.sto, alo)).?.state); }
test "tries are capped: an item that keeps failing stops being retried" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var cfg = cfgFlow(); cfg.retr_coun_maxz = 1; var ses = rg.ses(cfg, .live); const alo = rg.aren.allocator(); const fl = try appr.planFlow(&rg.sto, alo, "u", "t", &.{"send Mom x"}, 1); const its = try flo.itemsOf(&rg.sto, alo, fl); try flo.itemTry(&rg.sto, its[0].id); const res = try fq.run(&ses, fl, .{}); try T.expectEqual(@as(u32, 1), res.fail); try T.expectEqualStrings("fail", (try flo.itemsOf(&rg.sto, alo, fl))[0].state); try T.expectEqual(@as(i64, 0), try rg.num("Z.st.sent.length")); }
